}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "level",
      "operator": "in",
      "value": ["error", "warn"]
    },
    {
      "field": "service",
      "operator": "starts_with",
      "value": "api-"
    },
    {
      "field": "msg",
      "operator": "contains",
      "value": "timeout"
    }
