  "sort_field": "ts",
  "sort_order": "desc"
}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "level",
      "operator": "eq",
      "value": "error"
    }
  ],
  "aggregations": [
    {
      "type": "count",
      "field": "*",
      "alias": "error_count"
    },
    {
      "type": "unique",
      "field": "service",
      "alias": "affected_services"
    },
    {
      "type": "cardinality",
      "field": "host",
      "alias": "affected_hosts"
    }
  ],
  "group_by": ["service", "level"],
  "limit": 1000
}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "level",
      "operator": "in",
      "value": ["error", "warn"]
    }
