  "time_series": true,
  "time_granularity": "hour",
  "aggregations": [
    {
      "type": "count",
      "field": "*",
      "alias": "events_per_hour"
    }
  ],
  "group_by": ["service"],
  "limit": 2000
}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "severity_num",
      "operator": "gte",
      "value": 3
    },
    {
      "field": "service",
      "operator": "ne",
      "value": "health-check"
    }
  ],
  "aggregations": [
    {
      "type": "avg",
      "field": "severity_num",
      "alias": "avg_severity"
