  "time_granularity": "minute",
  "sort_field": "severity_num",
  "sort_order": "desc",
  "limit": 1000
}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "level",
      "operator": "in",
      "value": ["error", "critical"]
    },
    {
      "field": "msg",
      "operator": "regex",
      "value": "(failed|denied|blocked|unauthorized|breach)"
    }
  ],
  "text_search": "security",
  "aggregations": [
    {
      "type": "count",
      "field": "*",
      "alias": "security_events"
    },
    {
      "type": "unique",
      "field": "src_ip",
      "alias": "unique_sources"
    },
    {
      "type": "cardinality",
      "field": "user_id",
      "alias": "affected_users"
    }
  ],
  "group_by": ["service", "src_ip"],
  "time_series": true,
  "time_granularity": "minute",
  "limit": 5000
}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "msg",
      "operator": "regex",
      "value": "\\b(?:error|exception|failure|timeout)\\b.*\\d{3,4}ms"
    },
    {
      "field": "trace_id",
      "operator": "regex",
      "value": "^[a-f0-9]{16,32}$"
    },
    {
      "field": "status",
      "operator": "gte",
      "value": 400
    }
  ],
  "aggregations": [
    {
      "type": "count",
      "field": "*",
      "alias": "total_issues"
    },
    {
      "type": "unique",
      "field": "status",
      "alias": "status_codes"
    }
  ],
  "group_by": ["service", "level"],
  "limit": 1000
}

{
  "start_time": "2025-10-08T00:00:00Z",
  "end_time": "2025-10-10T23:59:59Z",
  "filters": [
    {
      "field": "level",
      "operator": "in",
