  "aggregations": [
    {
      "type": "count",
      "field": "*",
      "alias": "total_events"
    },
    {
      "type": "sum",
      "field": "status",
      "alias": "total_status_codes"
    },
    {
      "type": "avg",
      "field": "severity_num",
      "alias": "avg_severity"
