{
  "title": "Custom Brute Force Detection",
  "description": "Detects brute force login attempts with multiple failed logins",
  "severity": "high",
  "author": "Security Team",
  "tags": ["authentication", "brute-force", "security"],
  "logsource": {
    "category": "authentication",
    "product": "linux"
  },
  "detection": {
    "selection": {
      "event_type": "login_failed",
      "status_code": [401, 403]
    },
    "condition": "selection | count(by=[\"src_ip\"]) > 5"
  },
  "attack_techniques": ["T1110"],
  "kill_chain_phases": ["credential-access"],
  "references": ["https://attack.mitre.org/techniques/T1110/"],
  "falsepositives": ["Legitimate users with expired passwords"],
  "enabled": true
}

